func solveNQueens(n int) [][]string {
    var res [][]string
    queens := make([]int, n) // queens[row] = col
    cols := make(map[int]bool)
    diag1 := make(map[int]bool) // row - col
    diag2 := make(map[int]bool) // row + col

    var backtrack func(row int)
    backtrack = func(row int) {
        if row == n {
            board := make([]string, n)
            for i, col := range queens {
                row := make([]byte, n)
                for j := range row {
                    row[j] = '.'
                }
                row[col] = 'Q'
                board[i] = string(row)
            }
            res = append(res, board)
            return
        }
        for col := 0; col < n; col++ {
            if cols[col] || diag1[row-col] || diag2[row+col] {
                continue
            }
            queens[row] = col
            cols[col] = true
            diag1[row-col] = true
            diag2[row+col] = true
            backtrack(row + 1)
            cols[col] = false
            diag1[row-col] = false
            diag2[row+col] = false
        }
    }
    backtrack(0)
    return res
}
